import { test, expect } from '@playwright/test';
import path from 'path';
import { openAddCandidate, fillStep1, closeAddCandidate, identifyingIn, stamp, uniquePhone, ANON_HINT, EMPLOYERS } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const ts = stamp();
const FIRST = 'QA-AUTO-d4f6e7';
const LAST = `W${ts}`;
const EMAIL = `qa-auto-d4f6e7-w${ts}@example.com`;
const FIELD = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';

test.describe('Anonymous candidate: AI title and summary without identifying details (#d4f6e7)', () => {
  test('«הוספת מועמד» step 2: headline «… – Backend ב-Wix» gives a title and summary without employer, name, phone or e-mail; hint under the title @desktop #d4f6e7', async ({ page }) => {
    test.setTimeout(120_000);
    const phone = uniquePhone();

    // 1. Step 1 — headline with the name and the employer, «כמה מילים» with two employers
    const dialog = await openAddCandidate(page);
    await fillStep1(dialog, {
      first: FIRST, last: LAST, phone, email: EMAIL, field: FIELD,
      headline: `${FIRST} ${LAST} – Backend ב-Wix`,
      about: 'מפתח Backend ב-Wix כבר שלוש שנים, לפני כן עבד ב-Monday.com.',
    });

    // 2. Step 2 — wait for the AI title and summary
    const title = page.locator('#c-ai-title');
    const summary = page.locator('#c-ai-summary');
    await expect(title).toHaveValue(/\S/, { timeout: 60_000 });
    await expect(summary).toHaveValue(/\S/, { timeout: 60_000 });
    const t = await title.inputValue();
    const s = await summary.inputValue();
    test.info().annotations.push({ type: 'ai-title', description: t }, { type: 'ai-summary', description: s });

    // No employer / name / contacts (מה רצוי p.1: «Backend ב-Wix» → «מפתח/ת Backend»; §29 AC02–AC05)
    const who = { names: [FIRST, LAST], employers: [EMPLOYERS.wix, EMPLOYERS.monday], phone, email: EMAIL };
    expect(identifyingIn(t, who), `title: «${t}»`).toEqual([]);
    expect(identifyingIn(s, who), `summary: «${s}»`).toEqual([]);
    expect(t, 'the role stays in the title').toMatch(/Backend/i);

    // Hint under the title (מה רצוי p.2)
    await expect(dialog.getByText(ANON_HINT.he)).toBeVisible();

    // 3. Close without saving
    await closeAddCandidate(page, 'יציאה');
    await expect(dialog).toBeHidden();
  });
});
